BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(27);
INSERT INTO auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) VALUES
('fd000000-0000-4000-8000-000000000001','authenticated','authenticated','discussion-admin@local.test','{}','{}'),
('fd000000-0000-4000-8000-000000000002','authenticated','authenticated','discussion-outsider@local.test','{}','{}');
INSERT INTO public.organizations(id,name,username,type,join_code) VALUES('fd100000-0000-4000-8000-000000000001','Discussion fixtures','discussion-fixtures','school','739991');
INSERT INTO public.organization_members(organization_id,user_id,role,status) VALUES('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001','admin','active');
INSERT INTO plugin_data.csf_terms(id,organization_id,code,label,school_year,semester) VALUES('fd200000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','F30','Fall 2030','2030-2031','fall');
INSERT INTO plugin_data.csf_sheet_sync_destinations(id,organization_id,spreadsheet_file_id,sheet_id,kind,term_id,is_test,configured_by,managed_headers) VALUES('fd400000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','fictional-discussion-copy',0,'applications','fd200000-0000-4000-8000-000000000001',true,'fd000000-0000-4000-8000-000000000001','["Record ID","Comments","Source version"]');
SELECT extensions.is((SELECT discussion_transport FROM plugin_data.csf_sheet_sync_destinations WHERE id='fd400000-0000-4000-8000-000000000001'),'native','existing destinations preserve native mode');
SELECT extensions.is(plugin_data.csf_sheet_discussion_configuration('fd400000-0000-4000-8000-000000000001'),'{}'::jsonb,'native acceptance configuration remains unchanged');
SELECT extensions.throws_ok($$SELECT plugin_data.csf_configure_sheet_discussion_transport('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000002','fd400000-0000-4000-8000-000000000001','column')$$,'P0001','Not authorized.','outsider cannot configure discussion mode');
SELECT extensions.lives_ok($$SELECT plugin_data.csf_configure_sheet_discussion_transport('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','column')$$,'authorized staff configures ordinary column');
SELECT extensions.is(plugin_data.csf_sheet_discussion_configuration('fd400000-0000-4000-8000-000000000001'),'{"discussion_transport":"column"}'::jsonb,'column transport is part of acceptance identity');
SELECT extensions.is((SELECT comment_capability FROM plugin_data.csf_sheet_sync_destinations WHERE id='fd400000-0000-4000-8000-000000000001'),'pending','mode change requires a new capability check');
SELECT extensions.lives_ok($$SELECT plugin_data.csf_configure_sheet_discussion_transport('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','column')$$,'same mode retry is idempotent');
SELECT extensions.is((SELECT count(*)::integer FROM plugin_data.csf_admin_audit_events WHERE organization_id='fd100000-0000-4000-8000-000000000001' AND action='sheet_sync.discussion_configured'),1,'mode retry preserves one audit event');
SELECT extensions.ok(NOT has_function_privilege('authenticated','plugin_data.csf_configure_sheet_discussion_transport(uuid,uuid,uuid,text)','EXECUTE'),'browser cannot configure discussion mode');
SELECT extensions.ok(NOT has_function_privilege('service_role','plugin_data.csf_sheet_discussion_configuration(uuid)','EXECUTE'),'internal configuration helper is owner-only');
INSERT INTO plugin_data.csf_sheet_sync_bindings(organization_id,destination_id,record_kind,record_id,logical_key,sheet_id) VALUES('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001','fixture',0);
SELECT extensions.throws_ok($$SELECT plugin_data.csf_configure_sheet_discussion_transport('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','native')$$,'P0001','Create a new destination to change a discussion transport already in use.','used discussion provenance cannot change');
SELECT extensions.ok(NOT has_table_privilege('service_role','plugin_data.csf_sheet_sync_bindings','UPDATE'),'exported baseline remains RPC-only');
SELECT extensions.ok(to_regprocedure('plugin_data.csf_finish_sheet_sync_export(uuid,uuid,uuid,text,text,text,text)') IS NOT NULL,'finish accepts a complete Comments receipt');
INSERT INTO plugin_data.csf_cohorts(id,organization_id,graduation_year,label) VALUES('fd500000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001',2033,'Class of 2033');
INSERT INTO plugin_data.csf_profiles(id,organization_id,first_name,last_name,normalized_first_name,normalized_last_name) VALUES('fd300000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','Fictional','Student','fictional','student');
INSERT INTO plugin_data.csf_term_applications(id,organization_id,profile_id,cohort_id,term_id,source,status) VALUES('fd600000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','fd300000-0000-4000-8000-000000000001','fd500000-0000-4000-8000-000000000001','fd200000-0000-4000-8000-000000000001','manual','submitted');
SELECT plugin_data.csf_set_sheet_sync_destination_state('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001',true,true,'available');
CREATE TEMP TABLE column_fixture(k text PRIMARY KEY,v jsonb);
INSERT INTO column_fixture VALUES('queue',plugin_data.csf_queue_sheet_sync_record('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001'));
INSERT INTO column_fixture VALUES('lease',plugin_data.csf_claim_sheet_sync_destination('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001',true));
INSERT INTO column_fixture SELECT 'export',to_jsonb(x) FROM plugin_data.csf_claim_sheet_sync_exports('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM column_fixture WHERE k='lease'),1) x;
SELECT extensions.throws_ok($$SELECT plugin_data.csf_finish_sheet_sync_export('fd100000-0000-4000-8000-000000000001',(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='export'),(SELECT (v->>'lease_token')::uuid FROM column_fixture WHERE k='export'),'exported','version',NULL)$$,'P0001','A column export requires its complete Comments receipt.','old finish cannot claim a column export without baseline');
SELECT extensions.lives_ok($$SELECT plugin_data.csf_finish_sheet_sync_export('fd100000-0000-4000-8000-000000000001',(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='export'),(SELECT (v->>'lease_token')::uuid FROM column_fixture WHERE k='export'),'exported','version',NULL,'Original discussion')$$,'column write saves baseline');
SELECT extensions.is((SELECT last_export_comments FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='fd400000-0000-4000-8000-000000000001'),'Original discussion','exact written text is persisted');
SELECT extensions.throws_ok($$SELECT plugin_data.csf_finish_sheet_sync_export('fd100000-0000-4000-8000-000000000001',(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='export'),(SELECT (v->>'lease_token')::uuid FROM column_fixture WHERE k='export'),'exported','version',NULL,'Changed receipt')$$,'P0001','Export receipt conflicts with this attempt result.','same attempt cannot change Comments receipt');
SELECT extensions.throws_ok($$SELECT plugin_data.csf_record_sheet_sync_change('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001',(SELECT v->>'source_version' FROM column_fixture WHERE k='export'),'comment-v1','{"action":"comment","comments":"A reply","previous_comments":"wrong"}',(SELECT (v->>'poll_lease_token')::uuid FROM column_fixture WHERE k='lease'))$$,'P0001','The exported Comments baseline changed.','stale original cell cannot become a valid proposal');
INSERT INTO column_fixture VALUES('change',plugin_data.csf_record_sheet_sync_change('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001',(SELECT v->>'source_version' FROM column_fixture WHERE k='export'),'comment-v1','{"action":"comment","comments":"A reply","previous_comments":"Original discussion"}',(SELECT (v->>'poll_lease_token')::uuid FROM column_fixture WHERE k='lease')));
SELECT extensions.is(plugin_data.csf_record_sheet_sync_change('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001',(SELECT v->>'source_version' FROM column_fixture WHERE k='export'),'comment-v2','{"action":"comment","comments":"A reply","previous_comments":"Original discussion"}',(SELECT (v->>'poll_lease_token')::uuid FROM column_fixture WHERE k='lease'))->>'status','pending','repeat poll preserves pending edit hold');
SELECT extensions.is((SELECT count(*)::integer FROM plugin_data.csf_sheet_sync_local_messages WHERE organization_id='fd100000-0000-4000-8000-000000000001'),0,'Sheet edit does not publish before review');
SELECT extensions.lives_ok($$SELECT plugin_data.csf_review_sheet_sync_change('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001',(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='change'),true,'Reviewed the external reply')$$,'staff accepts comment without deciding application');
SELECT extensions.is((SELECT body FROM plugin_data.csf_sheet_sync_local_messages WHERE id=(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='change')),E'Google Sheets edit (reviewed):\nA reply','accepted edit preserves its Google Sheets origin');
SELECT extensions.is((SELECT decision_status FROM plugin_data.csf_term_applications WHERE id='fd600000-0000-4000-8000-000000000001'),'pending','comment acceptance never approves application');
SELECT plugin_data.csf_review_sheet_sync_change('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001',(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='change'),true,'Reviewed the external reply');
SELECT extensions.is((SELECT count(*)::integer FROM plugin_data.csf_sheet_sync_local_messages WHERE organization_id='fd100000-0000-4000-8000-000000000001'),1,'retry does not duplicate imported discussion');

SELECT extensions.throws_ok($$SELECT plugin_data.csf_reconcile_sheet_sync_export('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001',(SELECT (v->>'id')::uuid FROM column_fixture WHERE k='export'),true,'verified-version','Checked provider result')$$,'P0001','A column write requires its complete Comments receipt. Keep this write on hold.','reconciliation cannot bypass Comments baseline receipt');
INSERT INTO plugin_data.csf_sheet_sync_changes(organization_id,destination_id,record_kind,record_id,source_version,remote_version,payload) VALUES('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001','discard-fixture','discard-v1','{"action":"comment","comments":"Discarded edit","previous_comments":"Original discussion"}');
CREATE TEMP TABLE before_discard AS SELECT scope_revision FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='fd400000-0000-4000-8000-000000000001';
SELECT plugin_data.csf_review_sheet_sync_change('fd100000-0000-4000-8000-000000000001','fd000000-0000-4000-8000-000000000001',(SELECT id FROM plugin_data.csf_sheet_sync_changes WHERE remote_version='discard-v1'),false,'Keep the original discussion');
SELECT extensions.is((SELECT scope_revision FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='fd400000-0000-4000-8000-000000000001'),(SELECT scope_revision+1 FROM before_discard),'discard creates a new restore version');
SELECT extensions.ok(EXISTS(SELECT 1 FROM plugin_data.csf_sheet_writeback_ledger WHERE destination_id='fd400000-0000-4000-8000-000000000001' AND source_version=md5(plugin_data.csf_sheet_sync_destination_snapshot('fd100000-0000-4000-8000-000000000001','fd400000-0000-4000-8000-000000000001','application','fd600000-0000-4000-8000-000000000001')::text) AND status='pending_export'),'discard queues authoritative Comments restoration');
SELECT * FROM extensions.finish();
ROLLBACK;
